/*!
 * @file usbcpower4_app.h
 * @brief TPS26750A application configuration for USB-C Power 4 Click.
 * @details Contains a Low Region image generated for dual-role power operation
 * with source and sink capabilities configured for up to 240 W at 48 V. The
 * configuration has no preferred power role and disables USB data, BC1.2
 * legacy charging, and liquid detection.
 */

#ifndef USBCPOWER4_APP_H
#define USBCPOWER4_APP_H

#include <stdint.h>

/**
 * @brief USB-C Power 4 TPS26750A application image.
 * @details Low Region image generated by TI USBCPD Application Customization
 * Tool v2.0.0 using TPS26750A base firmware FB09.17.02__RC5.bin.
 */
extern const uint8_t usbcpower4_app_image[];

/**
 * @brief USB-C Power 4 TPS26750A application image size.
 * @details Size of the application image in bytes.
 */
extern uint32_t usbcpower4_app_image_size;

#endif // USBCPOWER4_APP_H
